INSERT INTO flickr_edin VALUES (4844926500, '2010-07-07 22:27:03', '%C3%A8 che bisognava testimoni%C3%A0%21|17mm|ad ogni modo%2C mi ostino a metterle cronologicamente%2C senn%C3%B2 mi rimane il cruccio|bokeh|caledonia|dof|e-p1|edimburgo|edinburgh|f2.8|l%27idea era %28%C3%A8%29 quella di fare la solita cronistoria...ma l%27%C3%A8 dura trovare foto decenti per ogni giorno...|m.zuiko_17mm_f2.8|ma costava troppo%2C col batacchio e tutto almeno 600 euri per uno adatto alla mia personcina...|olympus|pen|scotland|scottish inside|scozia|voglio il kilt%21', '57688343@N00', '0101000020346C0000513D91F134DD1341435FE52AE68F2441');
